package com.jobradar.taxonomy.skill;import java.util.Set;import com.jobradar.common.api.PaginatedResponse;import com.jobradar.common.exception.*;import com.jobradar.common.pagination.PaginationParameters;import com.jobradar.taxonomy.common.TaxonomySupport;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true)public class SkillService{private static final Set<String>SORTS=Set.of("name","slug","opportunityCount","createdAt");private final SkillRepository repo;public SkillService(SkillRepository r){repo=r;}public PaginatedResponse<SkillDto> browse(String q,PaginationParameters p,boolean popular,boolean admin){String query=q==null||q.isBlank()?null:q.trim();String sort=p.getSort().equals("createdAt")?(popular?"opportunityCount":"name"):p.getSort();if(!SORTS.contains(sort))throw new BadRequestException("Unsupported sort field: "+sort);Pageable pageable=PageRequest.of(p.getPage(),p.getSize(),Sort.by(popular?Sort.Direction.DESC:Sort.Direction.fromString(p.getDirection()),sort));Page<SkillEntity> result=admin?repo.adminBrowse(query,pageable):repo.browse(query,pageable);return PaginatedResponse.from(result.map(SkillDto::from));}@Transactional public SkillDto create(SkillRequest r){String n=r.skillName().trim(),s=r.slug()==null||r.slug().isBlank()?TaxonomySupport.slug(n):TaxonomySupport.slug(r.slug());duplicate(repo.existsByNameIgnoreCase(n)||repo.existsBySlugIgnoreCase(s));return SkillDto.from(repo.save(new SkillEntity(n,s)));}@Transactional public SkillDto update(Integer id,SkillRequest r){SkillEntity e=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Skill not found"));String n=r.skillName().trim(),s=r.slug()==null||r.slug().isBlank()?TaxonomySupport.slug(n):TaxonomySupport.slug(r.slug());duplicate(repo.existsByNameIgnoreCaseAndIdNot(n,id)||repo.existsBySlugIgnoreCaseAndIdNot(s,id));e.update(n,s);return SkillDto.from(e);}private void duplicate(boolean b){TaxonomySupport.duplicate(b,"Skill");}@Transactional public void active(Integer id,boolean a){repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Skill not found")).setActive(a);}}
